<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Admission Tests</h2><a class="btn btn-primary" href="<?= base_url('school/admission/tests/create') ?>">Create test</a></div><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Test</th><th>Circular</th><th>Date & time</th><th>Marks</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($items as $t): ?><tr><td><?= esc($t->title) ?><br><small><?= esc($t->school_name) ?></small></td><td><?= esc($t->circular_title) ?></td><td><?= esc($t->test_date) ?> <?= esc($t->start_time) ?></td><td><?= $t->total_marks ?> / pass <?= $t->pass_marks ?></td><td><?= esc(ucfirst($t->status)) ?></td><td><a href="<?= base_url('school/admission/tests/edit/'.$t->token) ?>">Edit</a></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="6" class="text-center text-muted">No admission tests.</td></tr><?php endif ?></tbody></table></div></div></div>
